import { badge, button, escapeHtml as e, money, pageHeading, emptyState } from "./ui.js";
import { feeInvoices, feeStudents } from "./fees-data.js";
const currency = (amount) => money(amount / 100);
const err = '<p class="form-error" role="alert" hidden></p>';
export function feesPage({ state, context, portal = {} }) {
  const all = feeInvoices(state, context), parent = context.role === "parent", admin = context.role === "admin", tab = portal.feeTab || "invoices", query = String(portal.feeQuery || "").toLowerCase(), status = portal.feeStatus || "all";
  const student = (id) => state.students.find((item) => item.id === id);
  const invoices = all.filter((item) => (!portal.feeChild || portal.feeChild === "all" || item.studentId === portal.feeChild) && (status === "all" || status === "unpaid" && item.balance > 0 || status === "part-paid" && item.paid > 0 && item.balance > 0 || status === item.status) && (!query || [item.title, student(item.studentId)?.name, student(item.studentId)?.admissionNumber, student(item.studentId)?.className].join(" ").toLowerCase().includes(query)));
  const due = all.reduce((sum, item) => sum + item.balance, 0), paid = all.reduce((sum, item) => sum + item.paid, 0), unpaid = new Set(all.filter((item) => item.balance > 0).map((item) => item.studentId)).size;
  return `${pageHeading(parent ? "School fees" : "School fee management", parent ? "All linked children · Demo online payments" : "Invoices, reminders and unpaid students · School-scoped demo", `${admin ? button("Issue fee invoice", "portal-invoice-new") : ""}${!parent ? button("Export fee register", "portal-fees-export", { variant: "secondary" }) : ""}`)}
    <div class="portal-stats"><section class="surface portal-card"><span>Outstanding</span><strong>${currency(due)}</strong></section><section class="surface portal-card"><span>Recorded payments</span><strong>${currency(paid)}</strong></section><section class="surface portal-card"><span>Students with unpaid fees</span><strong>${unpaid}</strong></section></div>
    <div class="portal-tabs">${[["invoices", "Invoices"], ["payments", "Payment history"], ...(!parent ? [["unpaid", "Unpaid students"], ["reminders", "Reminders"]] : [])].map(([id, label]) => button(label, "portal-fee-tab", { value: id, variant: id === tab ? "primary" : "secondary" })).join("")}</div>
    <section class="surface portal-card"><div class="portal-filters"><label>Student<select data-change="portal-fee-child"><option value="all">All students</option>${feeStudents(state, context).map((item) => `<option value="${e(item.id)}" ${portal.feeChild === item.id ? "selected" : ""}>${e(item.name)} · ${e(item.className)}</option>`).join("")}</select></label><label>Status<select data-change="portal-fee-status">${[["all", "All statuses"], ["unpaid", "Any unpaid balance"], ["overdue", "Overdue"], ["paid", "Paid"], ["part-paid", "Part paid"]].map(([id, label]) => `<option value="${id}" ${status === id ? "selected" : ""}>${label}</option>`).join("")}</select></label><label>Search<input type="search" data-change="portal-fee-query" value="${e(portal.feeQuery || "")}" placeholder="Name, admission or class"></label></div></section>
    ${tab === "payments" ? `<section class="surface portal-card"><h2>Payment history</h2>${invoices.flatMap((invoice) => invoice.payments.map((payment) => `<div class="portal-list-link"><div><strong>${e(student(invoice.studentId).name)}</strong><p>${e(payment.reference)} · ${e(payment.method)}</p><small>${e(payment.at.slice(0, 10))} · ${e(invoice.title)}</small></div><div><strong>${currency(payment.amount)}</strong>${button("Receipt", "portal-receipt", { value: payment.id, variant: "secondary" })}</div></div>`)).join("") || "<p>No payments recorded in this view.</p>"}</section>` : tab === "reminders" ? `<section class="surface portal-card"><h2>Fee reminder log</h2><p>Portal reminders only. One reminder per guardian / invoice / day. Students without linked guardians are reported for school follow-up.</p>${(state.feeReminders || []).filter((item) => invoices.some((invoice) => invoice.id === item.invoiceId)).slice().reverse().map((item) => `<div class="portal-list-link"><div><strong>${e(student(item.studentId).name)}</strong><p>${e(state.accounts.find((person) => person.id === item.parentId)?.name)} · ${e(item.day)}</p></div>${badge("Added to parent inbox", "green")}</div>`).join("") || "<p>No reminders recorded.</p>"}</section>` : tab === "unpaid" ? `<form data-form="portal-fee-reminders"><section class="surface portal-card"><h2>Unpaid students</h2><p>One row per student with an outstanding balance. Search by class or admission number above.</p>${admin ? '<button class="button secondary">Preview selected reminders</button>' : ""}${[...new Set(invoices.filter((invoice) => invoice.balance > 0).map((invoice) => invoice.studentId))].map((id) => { const pupil = student(id), open = invoices.filter((invoice) => invoice.studentId === id && invoice.balance > 0); return `<div class="unpaid-student"><div><strong>${e(pupil.name)}</strong><p>${e(pupil.admissionNumber)} · Class ${e(pupil.className)}</p></div><div><strong>${currency(open.reduce((sum, invoice) => sum + invoice.balance, 0))}</strong><small>${open.length} unpaid invoice(s)</small></div><div>${open.map((invoice) => `<div class="portal-actions">${admin ? `<label class="portal-check"><input type="checkbox" name="invoiceIds" value="${e(invoice.id)}"> ${e(invoice.title)}</label>` : `<span>${e(invoice.title)}</span>`}${button("View invoice", "portal-invoice", { value: invoice.id, variant: "secondary" })}${admin ? button("Record payment", "portal-office", { value: invoice.id, variant: "secondary" }) : ""}</div>`).join("")}</div></div>`; }).join("") || '<p>No unpaid students in this view.</p>'}${err}</section></form>` : `<form data-form="portal-fee-reminders"><div class="portal-actions">${admin ? '<button class="button secondary">Preview selected reminders</button>' : ""}</div><div class="portal-feed">${invoices.filter((item) => tab !== "unpaid" || item.balance > 0).map((invoice) => `<article class="surface portal-card"><div class="portal-row">${admin && invoice.balance > 0 ? `<label class="portal-check"><input type="checkbox" name="invoiceIds" value="${e(invoice.id)}" aria-label="Remind ${e(student(invoice.studentId).name)}"> Select for reminder</label>` : ""}${badge(e(invoice.status), invoice.balance ? "amber" : "green")}</div><h2>${e(invoice.title)}</h2><p><strong>${e(student(invoice.studentId).name)}</strong> · ${e(student(invoice.studentId).admissionNumber)} · Class ${e(student(invoice.studentId).className)}</p><div class="fee-amounts"><div><small>Total</small><strong>${currency(invoice.total)}</strong></div><div><small>Paid</small><strong>${currency(invoice.paid)}</strong></div><div><small>Balance</small><strong>${currency(invoice.balance)}</strong></div></div><p>Due ${e(invoice.due)}</p><div class="portal-actions">${button("View invoice", "portal-invoice", { value: invoice.id, variant: "secondary" })}${parent && invoice.balance > 0 ? button("Pay online · Demo", "portal-pay", { value: invoice.id }) : ""}${admin && invoice.balance > 0 ? button("Record office payment", "portal-office", { value: invoice.id, variant: "secondary" }) : ""}</div></article>`).join("") || `<section class="surface">${emptyState("checkCircle", "No matching fees", "Change the filters to see more invoices.")}</section>`}</div>${err}</form>`}`;
}
export function invoiceDetails(state, context, id) {
  const invoice = feeInvoices(state, context).find((item) => item.id === id); if (!invoice) throw new Error("Choose an accessible invoice.");
  const student = state.students.find((item) => item.id === invoice.studentId);
  return `<div class="portal-card"><h3>${e(invoice.title)}</h3><p>${e(student.name)} · ${e(student.admissionNumber)} · Due ${e(invoice.due)}</p>${invoice.lines.map((line) => `<div class="portal-list-link"><span>${e(line.title)}</span><strong>${currency(line.amount)}</strong></div>`).join("")}<p>Paid ${currency(invoice.paid)} · Outstanding <strong>${currency(invoice.balance)}</strong></p><p class="portal-muted">Demonstration invoice. No real money is collected.</p></div>`;
}
export function invoiceForm(state, context) { return `<form data-form="portal-invoice-new" class="portal-form"><label>Student<select name="studentId">${feeStudents(state, context).map((student) => `<option value="${e(student.id)}">${e(student.name)} · ${e(student.className)}</option>`).join("")}</select></label><label>Fee description<input name="title" maxlength="120" required placeholder="Term 1 school fees"></label><div class="portal-form-grid"><label>Amount (LKR)<input type="number" step="0.01" min="0.01" max="1000000" name="amount" required></label><label>Due date<input name="due" type="date" required></label></div>${err}<button class="button primary">Issue demo invoice</button></form>`; }
export function officeForm(id) { return `<form data-form="portal-office" class="portal-form"><input type="hidden" name="invoiceId" value="${e(id)}"><label>Amount (LKR)<input type="number" name="amount" min="0.01" step="0.01" required></label><label>Office receipt reference<input name="reference" required maxlength="80" placeholder="OFFICE-DEMO-001"></label><p>Records a demo school-office payment. No money is collected.</p>${err}<button class="button primary">Record payment</button></form>`; }
export function checkoutView(state, context, id, step = "review") {
  const checkout = state.feeCheckouts.find((item) => item.id === id && item.parentId === context.account.id), invoice = feeInvoices(state, context).find((item) => item.id === checkout?.invoiceId);
  if (!invoice || !checkout) throw new Error("Choose your family checkout.");
  const actions = (target, label) => button(label, "portal-checkout-step", { value: id + "|" + target });
  if (checkout.status !== "pending") return `<div class="portal-card"><h3>${checkout.status === "success" ? "Demo payment successful" : checkout.status === "declined" ? "Demo payment declined" : "Checkout cancelled"}</h3><p>${checkout.status === "success" ? "Your school fee balance has been updated." : "No payment was recorded. You can start a new checkout."}</p>${checkout.status === "success" ? button("Download demo receipt", "portal-receipt", { value: state.feePayments.find((item) => item.checkoutId === id)?.id }) : ""}</div>`;
  return `<div class="portal-card"><div class="checkout-steps" aria-label="Checkout progress">${["review", "method", "confirm"].map((item, index) => `<span class="${step.startsWith(item) ? "active" : ""}">${index + 1}. ${item}</span>`).join("")}</div><p class="demo-payment-banner">DEMO ONLY · No real payment or card details</p>${step === "review" ? `${invoiceDetails(state, context, invoice.id)}${actions("method", "Continue to payment method")}` : step === "method" ? `<h3>Choose how to pay</h3><p>Simulated card or bank transfer</p>${actions("confirm-card", "Demo card · 4242")}${actions("confirm-bank", "Demo bank transfer")}` : `<form data-form="portal-checkout"><input type="hidden" name="id" value="${e(id)}"><input type="hidden" name="method" value="${step === "confirm-bank" ? "Demo bank" : "Demo card"}"><h3>Confirm ${currency(checkout.amount)}</h3><p>${step === "confirm-bank" ? "Demo bank transfer · TEST ACCOUNT" : "Demo Visa · 4242 4242 4242 4242 · 12/30 · Test card"}</p><label>Simulated gateway result<select name="outcome"><option value="success">Successful payment</option><option value="declined">Declined payment</option></select></label>${err}<button class="button primary">Confirm demo payment</button></form>`}<div class="portal-actions">${button("Cancel checkout", "portal-checkout-cancel", { value: id, variant: "secondary" })}</div></div>`;
}
export function receiptText(state, context, id) {
  const invoice = feeInvoices(state, context).find((item) => item.payments.some((payment) => payment.id === id)), payment = invoice?.payments.find((item) => item.id === id);
  if (!payment) throw new Error("Choose an accessible payment receipt.");
  const student = state.students.find((item) => item.id === invoice.studentId);
  return `SUSSEX COLLEGE NETWORK\nDEMO PAYMENT RECEIPT - NOT PROOF OF REAL PAYMENT\n\n${payment.reference}\nStudent: ${student.name}\nAdmission: ${student.admissionNumber}\nInvoice: ${invoice.title}\nAmount: ${currency(payment.amount)}\nMethod: ${payment.method}\nRecorded: ${payment.at}\nBalance: ${currency(invoice.balance)}\n\nNo real money collected.`;
}
